INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('lake-taupo-trout', 'Lake Taupō', 'Taupō, Waikato', 'NZ', 'Freshwater', '["rainbow trout", "brown trout"]'::jsonb, 'fishing-spot', true, 'A vast volcanic caldera lake holding wild rainbow and brown trout in extraordinary numbers. Troll the drop-offs, harl the river mouths, or fish the shoreline drift at dusk under the Kaimanawa ranges.', '{"lat": -38.75, "lng": 175.95}'::jsonb, '{"current": 10, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Overcast", "temperature": 52, "humidity": 80, "windSpeed": 12, "windDirection": "SW"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["6-7 weight fly rod or light spin combo", "Smelt patterns and Tasmanian Devils", "Warm layers", "Landing net"], "optional": ["Boat or guided charter", "Downrigger for deep trolling", "Headlamp for evening rise"]}'::jsonb, '["Winter spawning run (May-Sep)", "Evening smelting at river mouths", "Summer deep trolling"]'::jsonb, 'Beginner', '["A DOC Taupō Fishing District licence is required — Fish & Game licences are not valid here", "Fishing permitted only between 5am and midnight; 35cm minimum size", "Felt-soled boots are banned nationwide to prevent didymo spread"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('tongariro-river', 'Tongariro River', 'Tūrangi, Waikato', 'NZ', 'Fly Fishing', '["rainbow trout", "brown trout"]'::jsonb, 'duck-spot', true, 'New Zealand''s most famous trout river, feeding Lake Taupō from the volcanic plateau. Named pools like the Major Jones and Admirals hold running rainbows through the winter spawning season.', '{"lat": -38.99, "lng": 175.81}'::jsonb, '{"current": 8, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Light Rain", "temperature": 48, "humidity": 85, "windSpeed": 8, "windDirection": "W"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["6-weight fly rod (nymph or Spey)", "Glo-bugs and heavy nymphs", "Chest waders with studs", "Wading staff"], "optional": ["Guide hire", "Polarized sunglasses", "Thermal layers"]}'::jsonb, '["Winter run (Jun-Sep)", "After fresh rain", "Early morning"]'::jsonb, 'Intermediate', '["DOC Taupō Fishing District licence required", "Fly fishing only on most of the river — check the Taupō regulations", "Felt-soled boots prohibited; clean gear between waterways"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('bay-of-islands-marlin', 'Bay of Islands', 'Northland', 'NZ', 'Saltwater', '["striped marlin", "yellowtail kingfish", "snapper"]'::jsonb, 'fishing-spot', true, 'Subtropical waters where Zane Grey made his name. Big game boats chase striped marlin and tuna offshore in summer, while snapper and kingfish hold on the reefs and islands inshore.', '{"lat": -35.22, "lng": 174.12}'::jsonb, '{"current": 15, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Partly Cloudy", "temperature": 59, "humidity": 75, "windSpeed": 12, "windDirection": "SW"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Heavy game outfit for marlin, or 8000 spin for kingfish", "Skirted lures and live baits", "Fluorocarbon or wire leader", "Sun protection"], "optional": ["Charter booking", "Outriggers", "Jigging outfit"]}'::jsonb, '["Game season (Jan-May)", "Snapper year-round", "Tide changes around the islands"]'::jsonb, 'Advanced', '["No licence required for recreational sea fishing in New Zealand", "Daily bag and minimum size limits apply — check Fisheries NZ rules", "Marine reserves around the islands are no-take zones"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('hauraki-gulf-snapper', 'Hauraki Gulf', 'Auckland', 'NZ', 'Saltwater', '["snapper", "yellowtail kingfish", "john dory"]'::jsonb, 'duck-spot', false, 'Auckland''s front yard and one of the most productive snapper fisheries in the country. Work the foul ground and channels between the islands, or chase workups where kingfish and snapper smash bait balls.', '{"lat": -36.6, "lng": 174.9}'::jsonb, '{"current": 14, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Partly Cloudy", "temperature": 57, "humidity": 75, "windSpeed": 14, "windDirection": "SW"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Medium spin combo (20-30lb braid)", "Soft baits and slow jigs", "Berley", "Fluorocarbon leader"], "optional": ["Boat or charter", "Sounder", "Kayak for inshore reefs"]}'::jsonb, '["Spring snapper (Oct-Dec)", "Summer workups", "Changing tides"]'::jsonb, 'Beginner', '["No licence required for recreational sea fishing", "Snapper bag limit and 30cm minimum size apply in this area", "Check Fisheries NZ for current limits and closed areas"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('mataura-river', 'Mataura River', 'Gore, Southland', 'NZ', 'Fly Fishing', '["brown trout"]'::jsonb, 'fishing-spot', false, 'Southland''s dry fly river, famous for the ''Mataura mayfly'' hatch that brings hundreds of brown trout onto the surface at once. Easy wading and prolific insect life make it a fly fisher''s classic.', '{"lat": -46.19, "lng": 168.86}'::jsonb, '{"current": 6, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Cold and Clear", "temperature": 41, "humidity": 80, "windSpeed": 15, "windDirection": "SW"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["5-weight fly rod", "Mayfly duns and spinners", "Chest waders", "Fine tippet"], "optional": ["Guide hire", "Polarized sunglasses", "Windproof jacket"]}'::jsonb, '["Mayfly hatch (Nov-Feb)", "Evening rise in summer", "Overcast afternoons"]'::jsonb, 'Intermediate', '["Fish & Game Southland or national licence required", "Season generally runs Oct-Apr — most water is closed in winter", "No felt-soled boots; check and dry gear to prevent didymo"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('lake-wanaka-trout', 'Lake Wanaka', 'Wanaka, Otago', 'NZ', 'Freshwater', '["brown trout", "rainbow trout", "landlocked salmon"]'::jsonb, 'duck-spot', false, 'Deep glacial water ringed by the Southern Alps, holding browns, rainbows and landlocked quinnat salmon. Fish the shoreline shelves, or head up the Makarora and Matukituki inflows for sight fishing.', '{"lat": -44.7, "lng": 169.13}'::jsonb, '{"current": 7, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Clear", "temperature": 43, "humidity": 60, "windSpeed": 10, "windDirection": "NW"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["6-weight fly rod or light spin combo", "Small spinners and damsel patterns", "Polarized sunglasses", "Layered clothing"], "optional": ["Boat or kayak", "Guide for backcountry rivers", "Hiking boots"]}'::jsonb, '["Summer sight fishing (Dec-Mar)", "Early morning shoreline", "Cicada season (Jan-Feb)"]'::jsonb, 'Intermediate', '["Fish & Game Otago or national licence required", "Backcountry rivers may need a separate backcountry licence endorsement", "Check season dates — many tributaries close over winter"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('marlborough-sounds-blue-cod', 'Marlborough Sounds', 'Picton, Marlborough', 'NZ', 'Saltwater', '["blue cod", "snapper", "yellowtail kingfish"]'::jsonb, 'fishing-spot', false, 'A maze of drowned river valleys with sheltered water in almost any wind. Blue cod over the rocky bottom, kingfish around the outer headlands, and increasingly good snapper in the warmer months.', '{"lat": -41.1, "lng": 174.0}'::jsonb, '{"current": 12, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Clear", "temperature": 52, "humidity": 70, "windSpeed": 10, "windDirection": "N"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Medium boat rod", "Bait rigs and soft baits", "Berley", "Measuring gauge"], "optional": ["Boat or water taxi", "Sounder", "Jigging outfit for kingfish"]}'::jsonb, '["Blue cod year-round", "Snapper (Dec-Mar)", "Calm mornings in the inner sounds"]'::jsonb, 'Beginner', '["No licence required for recreational sea fishing", "Blue cod has specific size, bag and seasonal rules in the Sounds — check Fisheries NZ", "Some areas are closed or restricted to protect the blue cod fishery"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('motueka-river', 'Motueka River', 'Tasman', 'NZ', 'Fly Fishing', '["brown trout"]'::jsonb, 'duck-spot', false, 'A clear freestone river running through the Tasman valleys, with sight fishing to large browns in low summer flows and willow-lined runs that hold fish through the season.', '{"lat": -41.28, "lng": 172.95}'::jsonb, '{"current": 8, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Overcast", "temperature": 50, "humidity": 75, "windSpeed": 6, "windDirection": "SW"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["5-6 weight fly rod", "Cicada and mayfly patterns", "Chest waders", "Polarized sunglasses"], "optional": ["Guide hire", "Wading staff", "Long fine leader"]}'::jsonb, '["Summer sight fishing (Dec-Mar)", "Cicada season (Jan-Feb)", "Evening rise"]'::jsonb, 'Advanced', '["Fish & Game Nelson/Marlborough or national licence required", "Season generally Oct-Apr on most water — check regional regulations", "Felt-soled boots banned; clean gear between rivers"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('kaikoura-offshore', 'Kaikōura Offshore', 'Kaikōura, Canterbury', 'NZ', 'Saltwater', '["blue cod", "hāpuku", "albacore tuna"]'::jsonb, 'fishing-spot', false, 'A deep submarine canyon runs close to shore here, putting big-water species within easy reach. Blue cod and hāpuku over the drop-offs with the Seaward Kaikōura range rising behind you.', '{"lat": -42.42, "lng": 173.7}'::jsonb, '{"current": 12, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Showers", "temperature": 48, "humidity": 80, "windSpeed": 16, "windDirection": "S"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Heavy boat rod for deep water", "Dropper rigs and jigs", "Wet weather gear", "Braided line"], "optional": ["Charter booking", "Electric reel for deep drops", "Seasickness tablets"]}'::jsonb, '["Settled weather windows", "Albacore (Jan-Apr)", "Slack tide over the canyon"]'::jsonb, 'Intermediate', '["No licence required for recreational sea fishing", "Marine mammal sanctuary — keep clear of whales and dolphins", "Bag and size limits apply; check Fisheries NZ for hāpuku rules"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('rotorua-lakes-trout', 'Rotorua Lakes', 'Rotorua, Bay of Plenty', 'NZ', 'Freshwater', '["rainbow trout", "brown trout"]'::jsonb, 'duck-spot', false, 'A dozen geothermal lakes within easy reach of each other, most stocked with hard-fighting rainbows. Jigging over the thermal springs on Rotoiti and fly fishing the stream mouths are local traditions.', '{"lat": -38.08, "lng": 176.27}'::jsonb, '{"current": 11, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Overcast", "temperature": 54, "humidity": 85, "windSpeed": 8, "windDirection": "W"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["6-weight fly rod or light jigging outfit", "Smelt flies and small jigs", "Warm layers", "Landing net"], "optional": ["Boat or charter", "Fish finder", "Headlamp for night jigging"]}'::jsonb, '["Winter jigging (Jun-Aug)", "Stream mouths after rain", "Summer evening rise"]'::jsonb, 'Beginner', '["Fish & Game Eastern or national licence required (not the Taupō DOC licence)", "Season and method rules vary lake by lake — check Eastern Fish & Game", "Felt-soled boots banned; check and dry gear between lakes"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('river-test-hampshire', 'River Test', 'Stockbridge, Hampshire', 'GB', 'Fly Fishing', '["brown trout", "grayling"]'::jsonb, 'fishing-spot', true, 'The birthplace of modern dry fly fishing. Gin-clear chalk stream water flows over ranunculus weed beds, with wild and stocked brown trout rising to duns in a landscape of manicured beats and thatched hatches.', '{"lat": 51.06, "lng": -1.49}'::jsonb, '{"current": 13, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Partly Cloudy", "temperature": 68, "humidity": 70, "windSpeed": 6, "windDirection": "SW"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["3-5 weight fly rod", "Dry flies — olives, mayfly, sedges", "Fine tippet", "Polarized sunglasses"], "optional": ["Beat booking", "Wading staff", "Landing net with soft mesh"]}'::jsonb, '["Mayfly season (late May-Jun)", "Evening rise in summer", "Grayling in autumn and winter"]'::jsonb, 'Advanced', '["Environment Agency rod licence required (free for ages 13-16)", "Nearly all beats are private — a day ticket or syndicate rod is essential", "Many beats are dry-fly-only and upstream-only; check beat rules"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('river-tweed-scotland', 'River Tweed', 'Kelso, Scottish Borders', 'GB', 'Fly Fishing', '["Atlantic salmon", "sea trout", "grayling"]'::jsonb, 'duck-spot', true, 'Scotland''s most productive salmon river, with a long autumn run that draws anglers from around the world. Broad, wadeable streams suit the Spey cast, and the beats below Kelso are legendary.', '{"lat": 55.6, "lng": -2.3}'::jsonb, '{"current": 14, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Overcast", "temperature": 63, "humidity": 80, "windSpeed": 10, "windDirection": "W"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["13-15ft Spey rod", "Sink tips and tube flies", "Chest waders with studs", "Wading staff"], "optional": ["Ghillie hire", "Beat booking well in advance", "Waterproof layers"]}'::jsonb, '["Autumn run (Sep-Nov)", "Spring fish (Feb-Apr)", "After a spate"]'::jsonb, 'Advanced', '["No Environment Agency licence needed in Scotland — you need the beat owner''s permission", "Salmon permits come from the estate or District Salmon Fishery Board", "No Sunday salmon fishing in Scotland; spring catch-and-release rules apply"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('river-spey-scotland', 'River Spey', 'Aberlour, Speyside', 'GB', 'Fly Fishing', '["Atlantic salmon", "sea trout"]'::jsonb, 'fishing-spot', true, 'The river that gave its name to the Spey cast. Fast, clean water running through whisky country, with a strong summer grilse run and wading that rewards a long line.', '{"lat": 57.5, "lng": -3.1}'::jsonb, '{"current": 13, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Light Rain", "temperature": 61, "humidity": 80, "windSpeed": 12, "windDirection": "SW"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["13-14ft Spey rod", "Traditional and tube flies", "Chest waders with studs", "Rain jacket"], "optional": ["Ghillie hire", "Beat permit", "Wading belt and staff"]}'::jsonb, '["Summer grilse (Jun-Aug)", "Spring run (Apr-May)", "Rising water after rain"]'::jsonb, 'Advanced', '["No rod licence in Scotland — a beat permit from the estate is required", "No salmon fishing on Sundays", "Mandatory catch-and-release applies early in the season — check local rules"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('chesil-beach-dorset', 'Chesil Beach', 'Dorset', 'GB', 'Saltwater', '["cod", "European bass", "mackerel"]'::jsonb, 'duck-spot', false, 'Eighteen miles of steep shingle on the Jurassic Coast, dropping into deep water close in. A storm beach that fishes best when it''s rough — cod and bass in winter, mackerel and bream through summer.', '{"lat": 50.6, "lng": -2.5}'::jsonb, '{"current": 17, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Windy", "temperature": 66, "humidity": 75, "windSpeed": 20, "windDirection": "SW"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["12-13ft beachcaster", "Grip leads for the tide", "Fresh lugworm or squid", "Head torch"], "optional": ["Tripod rod rest", "Waterproof beach shelter", "Studded boots for shingle"]}'::jsonb, '["After a south-westerly blow", "Night tides", "Winter cod (Nov-Feb)"]'::jsonb, 'Intermediate', '["No rod licence required for sea fishing in England", "Bass have minimum size and seasonal catch limits — check current rules", "Parts of the Fleet lagoon behind the beach are a protected nature reserve"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('river-towy-wales', 'River Towy', 'Llandeilo, Carmarthenshire', 'GB', 'Fly Fishing', '["sea trout", "Atlantic salmon", "brown trout"]'::jsonb, 'fishing-spot', false, 'Wales'' premier sewin river. Sea trout run up from Carmarthen Bay through the summer and are fished for at night, when big fish move into the pools under cover of darkness.', '{"lat": 51.88, "lng": -3.99}'::jsonb, '{"current": 15, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Overcast", "temperature": 64, "humidity": 80, "windSpeed": 8, "windDirection": "SW"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["9-10ft 7-weight fly rod", "Surface lures and sunk tubes for night", "Chest waders", "Head torch with red filter"], "optional": ["Association day ticket", "Wading staff", "Midge repellent"]}'::jsonb, '["Sewin run (Jun-Aug)", "Night fishing after dark", "After a summer spate"]'::jsonb, 'Advanced', '["Environment Agency rod licence required (covers England and Wales)", "A separate migratory salmonid licence endorsement is needed for salmon and sea trout", "Day tickets from local angling associations; national byelaws mandate salmon release"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('river-wye-barbel', 'River Wye', 'Hereford, Herefordshire', 'GB', 'Freshwater', '["barbel", "chub", "Atlantic salmon"]'::jsonb, 'duck-spot', false, 'A big, powerful river winding along the Welsh border. Hard-fighting barbel in the streamy gravel runs, chub under the willows, and a salmon run that was once among the finest in Britain.', '{"lat": 52.05, "lng": -2.72}'::jsonb, '{"current": 17, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Partly Cloudy", "temperature": 70, "humidity": 70, "windSpeed": 8, "windDirection": "W"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["1.75-2.25lb test curve barbel rod", "Feeder and pellet rigs", "Rod rest and landing net", "Bank sticks"], "optional": ["Day ticket from local club", "Chair or bedchair", "Head torch for evening"]}'::jsonb, '["Summer and autumn barbel", "Evenings in warm weather", "After rain colours the water"]'::jsonb, 'Intermediate', '["Environment Agency rod licence required", "Coarse fish close season applies on rivers (15 Mar - 15 Jun)", "Day tickets needed from the controlling club or landowner"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('norfolk-broads-pike', 'Norfolk Broads', 'Norfolk', 'GB', 'Freshwater', '["northern pike", "bream", "roach"]'::jsonb, 'fishing-spot', false, 'A network of shallow lakes and slow rivers created by medieval peat digging. Big pike hunt the reed-fringed margins in winter, and huge shoals of bream and roach fill the broads year-round.', '{"lat": 52.68, "lng": 1.5}'::jsonb, '{"current": 18, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Overcast", "temperature": 68, "humidity": 80, "windSpeed": 10, "windDirection": "E"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["2.75lb test curve pike rod", "Deadbaits and large lures", "Wire trace and unhooking mat", "Long forceps"], "optional": ["Boat hire", "Bite alarms", "Large landing net"]}'::jsonb, '["Winter pike (Oct-Mar)", "Summer bream at dawn", "Calm, overcast days"]'::jsonb, 'Intermediate', '["Environment Agency rod licence required", "Coarse close season applies on the rivers but not on most still broads", "Use wire traces and unhooking mats — pike welfare rules are enforced locally"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('lake-windermere', 'Windermere', 'Cumbria, Lake District', 'GB', 'Freshwater', '["northern pike", "perch", "Arctic char"]'::jsonb, 'duck-spot', false, 'England''s largest lake, deep and cold enough to hold Arctic char left over from the ice age. Big pike patrol the shallow bays, and perch shoals gather around the jetties and drop-offs.', '{"lat": 54.37, "lng": -2.94}'::jsonb, '{"current": 17, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Light Rain", "temperature": 63, "humidity": 85, "windSpeed": 10, "windDirection": "SW"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Medium spin or pike rod", "Lures, spinners and deadbaits", "Wire trace", "Waterproof jacket"], "optional": ["Boat hire", "Sounder", "Landing net and mat"]}'::jsonb, '["Autumn and winter pike", "Summer perch around structure", "Overcast, settled days"]'::jsonb, 'Beginner', '["Environment Agency rod licence required", "A permit is also needed from the Freshwater Biological Association or local controlling body", "Char fishing has specific seasonal and method rules"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('cornwall-bass-marks', 'West Cornwall Bass Marks', 'Penzance, Cornwall', 'GB', 'Saltwater', '["European bass", "pollack", "mackerel"]'::jsonb, 'fishing-spot', false, 'Granite headlands and surf beaches at the far south-west tip of Britain. Lure fishing for bass over the reefs and gullies at dawn is as good as it gets in UK saltwater angling.', '{"lat": 50.15, "lng": -5.07}'::jsonb, '{"current": 17, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Partly Cloudy", "temperature": 64, "humidity": 78, "windSpeed": 14, "windDirection": "W"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["9-10ft lure rod", "Surface lures and soft plastics", "Studded boots for rock marks", "Buoyancy aid"], "optional": ["Kayak for reef marks", "Head torch", "Tide tables"]}'::jsonb, '["Bass season (May-Oct)", "Dawn over the reefs", "Building surf on the beaches"]'::jsonb, 'Intermediate', '["No rod licence required for sea fishing in England", "Bass minimum size and monthly bag limits apply — check current DEFRA rules", "Rock marks are exposed — check tide and swell before fishing"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('river-tay-scotland', 'River Tay', 'Dunkeld, Perthshire', 'GB', 'Fly Fishing', '["Atlantic salmon", "northern pike", "brown trout"]'::jsonb, 'duck-spot', false, 'Britain''s largest river by flow, and the source of the biggest rod-caught salmon ever landed in the UK. Big water suited to harling from a boat or Spey casting the classic Perthshire beats.', '{"lat": 56.55, "lng": -3.6}'::jsonb, '{"current": 14, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Overcast", "temperature": 61, "humidity": 80, "windSpeed": 10, "windDirection": "SW"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["14-15ft Spey rod", "Heavy tube flies and sink tips", "Chest waders with studs", "Wading staff"], "optional": ["Ghillie and boat for harling", "Beat booking", "Thermal layers for spring"]}'::jsonb, '["Spring springers (Feb-Apr)", "Autumn run (Sep-Oct)", "After a rise in water"]'::jsonb, 'Advanced', '["No rod licence in Scotland — a permit from the beat or estate is required", "No salmon fishing on Sundays", "Spring catch-and-release rules apply; check the Tay District Salmon Fishery Board"]'::jsonb);
